head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = 'ULDSTF41620.xml';
scwin.vJobMode = "";
scwin.vIsurCd = "";
scwin.vIsurNm = "";
scwin.vBzProcsNo = "";
scwin.vSeq = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_set_ctrl = function() {
    scwin.fn_set_list_dd();
};
scwin.fn_set_list_dd = function() {
    edt_SDate.setValue('19000101');
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=LISTCMITCONTN_SEARCH_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.select.listcomitcontn.list.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_COM_NM) + "&{P}param02=" + $c.stf.getObjectValue(cmb_PERFM_YN) + "&{P}param03=" + $c.stf.getObjectValue(cmb_PERFM_YN) + "&{P}param04=" + $c.stf.getObjectValue(txb_LEADCOM) + "&{P}param05=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param06=" + $c.stf.getObjectValue(edt_EDate);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_open_dtl = async function(row) {
    var wth = 1100;
    var hgt = 600;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    scwin.vIsurCd = dts_List.getCellData(row, "ISUR_CD");
    scwin.vIsurNm = dts_List.getCellData(row, "COM_NM");
    await $c.frame.CreateDialogFrame("CMIT_CONTN", "/lstmgt/ULDSTF41621.gfm", "확약사항관리", pt.x, pt.y, wth, hgt, "window");
    dts_List.setRowPosition(row, 0);
};
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_List, "확약사항", "", 8, 0);
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.vJobMode = "M";
    scwin.fn_open_dtl(row);
    scwin.vJobMode = "";
};
scwin.btn_New_onclick = function() {
    scwin.vJobMode = "I";
    scwin.fn_open_dtl();
    scwin.fn_list_sync();
    scwin.vJobMode = "";
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_set_ctrl();
    scwin.fn_list_sync();
};
